def get_cols():
    return int(os.popen('tput cols', 'r').read().split()[0])
    #return int(subprocess.Popen(['tput','cols'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True).communicate()[0])

def get_rows():
    #return int(subprocess.Popen(['tput','lines'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True).communicate()[0])
    return int(os.popen('tput lines', 'r').read().split()[0])    
        


